# In Indian scripts an imperative is often the start of the past tense (Kannada ಕಳುಹಿಸಿ "send!" begins
# ಕಳುಹಿಸಿದ್ದೆ "I sent"; Bengali পাঠান begins পাঠানো "sent"), so these must not continue into a longer word.
WHOLE_WORD = {"send"}
_INDIC = "ऀ-ൿ"


# Tamil, Telugu, Kannada and Malayalam drop a word's final virama before a suffix (அரெஸ்ட் -> அரெஸ்டில்),
# and Malayalam final letters change (മകൻ -> മകനെ), so a final virama is optional and a final chillu
# also matches its suffixed form.
_VIRAMA = "्্੍્்్್്"
_CHILLU = {"ൻ": "ന", "ർ": "ര", "ൽ": "ല", "ൾ": "ള", "ൺ": "ണ"}


def _suffixable(f: str) -> str:
    if f and f[-1] in _VIRAMA:
        return f + "?"
    if f and f[-1] in _CHILLU:
        return f"{f[:-1]}(?:{f[-1]}|{_CHILLU[f[-1]]})"
    return f


def _frag(name: str, f: str) -> str:
    f = _suffixable(f)
    if name in WHOLE_WORD and any(ch >= "ऀ" for ch in f):
        return f"(?:{f})(?![{_INDIC}])"
    return f"(?:{f})"


def alt(*names: str) -> str:
    """One alternation of every fragment of the named concepts."""
    return "|".join(_frag(n, f) for n in names for f in C[n])
